<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class VendorCommission extends Model{protected $fillable=['vendor_id','order_id','gross','commission','net'];protected $casts=['gross'=>'decimal:2','commission'=>'decimal:2','net'=>'decimal:2'];public function vendor(){return $this->belongsTo(Vendor::class);}public function order(){return $this->belongsTo(Order::class);}}
